int factorial(int n) {
    if (n <= 1) return 1; // Base case
    return n * factorial(n - 1); // Recursive step
}

int countdown(int n) {
    if (n ___ 0) return 0; // Base Case
    return countdown(n - 1);
}

int tailFact(int n, int acc = 1) {
    if (n <= 1) return acc;
    return tailFact(n - 1, n * acc); // ___ call
}

int product(int n, int acc = ___) {
    if (n == 1) return acc;
    return product(n - 1, acc * n);
}

int fib(int n) {
    if (n ___ 1) return n;
    return fib(n - 1) + fib(n - 2);
}

void traverse(Node* node, ___ depth) {
    if (!node || depth > 1000) return;
    traverse(node->next, depth + 1);
}
